ent=\"Welcome to Lembaga Koko Malaysia\" />\n    </Head>\n\n    <form @submit.prevent=\"login\" method=\"post\">\n        <div class=\"alert alert-danger\" v-if=\"isError\">\n            Email or Password not match!\n        </div>\n\n        <VAlert :isShowValidation=\"false\" />\n\n        <div class=\"mb-3\">\n            <VInputWithBlockLabel\n                elId=\"email\"\n                label=\"Email\"\n                placeholder=\"Email\"\n                v-model:value=\"form.email\"\n                type=\"email\"\n                :error=\"form.errors.email\"\n            />\n        </div>\n\n        <div class=\"mb-3\">\n            <VInputPasswordWithBlockLabel\n                elId=\"password\"\n                label=\"Password\"\n                placeholder=\"Password\"\n                v-model:value=\"form.password\"\n                :error=\"form.errors.password\"\n            />\n        </div>\n\n        <div class=\"form-check mb-3\">\n            <input\n                class=\"form-check-input\"\n                type=\"checkbox\"\n                v-model=\"form.remember_me\"\n                id=\"rememberPasswordCheck\"\n            />\n            <label class=\"form-check-label\" for=\"rememberPasswordCheck\">\n                Remember password\n            </label>\n        </div>\n        <!--\n        <div class=\"mb-3\">\n            <VueRecaptcha\n                :sitekey=\"recaptchav2_sitekey\"\n                ref=\"elRecaptcha\"\n                @verify=\"onCaptchaVerify\"\n            />\n            <div v-if=\"form.errors.recaptcha\" class=\"row\">\n                <div class=\"col-12 text-danger font-error\">\n                    {{ form.errors.recaptcha }}\n                </div>\n            </div>\n        </div> -->\n\n        <div class=\"row justify-content-between\">\n            <div class=\"col-6\">\n                <Link href=\"/\" class=\"btn btn-secondary\">\n                    <span class=\"material-icons\"> chevron